using System.Security.Cryptography;
using System.Text;

public static class Passwords
{
    // One fast hash per guess, salt or not
    public static byte[] Hash(byte[] salt, string password) =>
        SHA256.HashData([.. salt, .. Encoding.UTF8.GetBytes(password)]);

    public static bool Verify(byte[] salt, byte[] stored, string password) =>
        CryptographicOperations.FixedTimeEquals(Hash(salt, password), stored);
}

using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Options;

public sealed class Passwords
{
    // PBKDF2-HMAC-SHA512 with a random salt; the default is 100,000
    private readonly PasswordHasher<User> _hasher = new(Options.Create(
        new PasswordHasherOptions { IterationCount = 220_000 }));

    public string Hash(User user, string password) =>
        _hasher.HashPassword(user, password);

    public bool Verify(User user, string password)
    {
        var result = _hasher.VerifyHashedPassword(user, user.PasswordHash, password);
        if (result == PasswordVerificationResult.SuccessRehashNeeded)
            user.PasswordHash = Hash(user, password); // raise the cost on login
        return result != PasswordVerificationResult.Failed;
    }
}
